document.addEventListener("DOMContentLoaded",async function(){try{const i=await fetch("/Catalog/GetCartCount"),n=await i.json(),t=document.getElementById("cartBadge");t&&(t.textContent=n.count>0?n.count:"0")}catch(n){console.error("Не удалось получить количество товаров:",n)}});document.addEventListener("DOMContentLoaded",function(){const n=document.querySelectorAll("[data-filter]"),t=document.querySelector("#filterSummary");n.forEach(function(i){i.addEventListener("click",function(){n.forEach(function(n){n.classList.remove("active","btn-primary");n.classList.add("btn-outline-secondary");n.setAttribute("aria-pressed","false")});i.classList.remove("btn-outline-secondary");i.classList.add("active","btn-primary");i.setAttribute("aria-pressed","true");t&&(t.textContent="Выбран фильтр: "+i.dataset.filter)})})});